grid=[[4]*13 for _ in range(20)]
markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# retain motif as given
motif={(0,0):5,(0,1):5,(1,-1):8,(1,0):5,(1,1):8,(2,-1):8,(2,0):5,(2,1):0}
# anchor position is repeated 5 at top of vertical 5 column
for r,c in markers:
    for (dr,dc),v in motif.items():
        rr,cc=r+dr,c+dc
        if 0<=rr<20 and 0<=cc<13:
            grid[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in grid))

